from pathlib import Path
import json, csv, re, shutil
from pypdf import PdfReader

ROOT=Path(__file__).resolve().parents[1]
WORK=ROOT.parent
cards=[]
def card(cat,title,body,source,tag='已核對'):
    cards.append(dict(cat=cat,title=title,body=body,source=source,tag=tag))
card('基本原則','先辨認活動性質，再決定可報項目','一般因公奉派出差，依交通、住宿、雜費三類審查。訓練、講習、競賽活動、授課及各項週報性質會議，另走保六第3點補助路徑。不能只看假單寫「公差」就一律發雜費；研討會、說明會應依實際內容與核派文件判斷。','保六第2、3點；中央第1、3點；彙編壹三（十一）（十二）')
card('基本原則','中央規定與保六內規如何一起用？','中央要點提供通用範圍，並容許機關在範圍內另定規定。保六已就住宿、雜費及特定活動訂定標準，先套用適用的內規；未規定處回到中央要點。115年3月「解釋彙編」是函示與個案參考，不能當成一份全面取代內規的新法。發現矛盾時送主計確認。','中央第15點；保六第1、5點；彙編前言')
card('基本原則','出差前要完成哪些核定？','確認公務必要性、活動性質、出差日期、行程、起訖地與交通方式。可用公文、電話、視訊或電子郵件處理者，不派公差。行程日數須事先核定，往返行程以不超過一日為原則；需額外住宿、改變行程或特殊運具時，併陳必要性。','中央第3點；保六第4點')
card('交通費','一般大眾運輸：先算上限，再看實付','將機關所在地到出差地的必要路程逐段列明，例如公車→捷運→臺鐵→目的地接駁。上限依適用交通工具及必要路程認定；申報仍按實際搭乘工具、艙等及實際支付金額，在上限內覈實報支。優惠票、轉乘折扣須反映實付，不能拿全票價替代較低實付。','中央第5點第1至4項；114生效問答Q1、Q5')
card('交通費','自駕汽車每公里3元；機車每公里2元','114年1月1日起按機關認定的必要路程公里數計算，自行租賃（含共享）汽、機車亦比照。不是自駕後再任選火車票價或較高金額。不得另報油料、過路橋、停車費；事故修理及對第三者賠償也不得以公款支付。特殊活動另受保六第3點限制，適用方式須確認。','中央第5點第6、7項；問答Q9至Q11；彙編壹五（七）')
card('交通費','里程怎麼認定？','地圖軟體、行駛路線、里程小數位及佐證要求，由機關本權責認定，中央未指定唯一地圖。建議留存起訖點、路線、里程與查詢日期；這是承辦作業建議，並非新增中央法定附件。計算後費用至元為止，角位四捨五入。','問答Q9；中央第5點第3項')
card('交通費','公務車、免費票、同仁便車','機關專備交通工具、免費票或搭乘便車的路段不得報交通費。共乘出差時，符合規定的駕駛可報自駕里程，搭乘同仁不能再按火車票價領取。其他自付且符合規定的路段應分開審查。','中央第5點第8項；彙編壹五（十三）（十四）')
card('交通費','親友接送與同仁共乘不能混為一談','彙編案例指出，親友駕駛自用汽機車接送，若親友及其他共乘者沒有政府機關奉派出差領交通費等重複公款支用，可由機關認定比照自駕。搭乘廠商車處理同一公務則屬便車，不適用親友接送解釋。請附事實說明送機關認定。','彙編壹五（十一）（十二）；106.12.12、107.1.9案例','個案認定')
card('交通費','高鐵不是本工具的預設計價方式','現有保六第2點列有高鐵，要求檢附票根或購票證明，並明定商務艙須簽奉機關首長核可。這份內規沒有寫「所有高鐵一律另簽」；承辦人115.09.23確認應只有商務艙另簽要求，本站不增設一般高鐵另簽限制。不得從一般條文推論每件高鐵都可報，尤其第3點活動僅補助火車票價。','保六第2(1)、3點；問答Q6；承辦人115.09.23確認')
card('交通費','商務艙與核定工具變更','保六明定搭乘商務艙須簽奉機關首長核可。若另有交通工具事前簽准規定，原則應照核定行程搭乘；不得先簽較貴工具再改搭便宜工具的商務艙。特殊變更及報支上限是否維持，交由機關依個案核處。','保六第2(1)點；問答Q6')
card('交通費','交通單據：保六要求較明確','保六要求飛機、高鐵、分等船舶、火車商務車廂或相同座位另附票根或購票證明。中央雖有當日往返或經費結報系統免附例外，現有保六文字未列；承辦先依內規備齊，是否採免附由主計確認。一般公車、捷運與一般火車仍應據實填列路線及金額；查價頁不是付款證明。','保六第2(1)點；中央第5點第4項','含待確認處')
card('交通費','計程車、公共自行車與接駁','公共自行車列在必要交通工具範圍；實際必要路段才可覈實。公民營客運可到達的地區，計程車除因業務需要經機關核准外不得報。住宿地到出差地的短程車資與購票手續費屬雜費範圍，避免再列交通費。不能把所有市區公車捷運都當短程雜費，須看是否屬出差必要行程。','中央第5點；彙編壹二（一）（三）（四）')
card('交通費','從住家出發：仍有機關起訖上限','依機關所在地與出差地認定上限。現行問答容許符合提前出發、延後返回情形，在不重複支領下，將相關上下班與出差實付合併於上限內核處；不是所有通勤都能加報。放假日先到辦公室拿資料再出發，住家到辦公室一段不得報。','問答Q2、Q3；彙編壹五（一）')
card('交通費','駐地不同於機關登記地址','機關有不同辦公地點時，彙編案例以實際辦公地點（駐在工作地）為起訖點。第二大隊案件應先確認實際服務駐地，不宜全部固定套總隊地址。必要路程仍由機關認定。','彙編壹五（二）；110.5.6主預督字第1100006236號')
card('交通費','個人定期票／TPASS','使用個人定期票出差，可按「票價÷優惠天數」計算當次或當天交通費，仍受報支上限約束；不把每一搭乘路段的全票價再相加。同一天、同一定期票避免重複計列，保六特殊活動限制仍須併審。','彙編壹五（二十二）；112.6.2主預字第1120101654號')
card('交通費','捷運常客回饋與當次優惠','使用個人電子票證搭乘北捷，按搭乘時票證實際扣款報支，無須再核算扣減次月常客回饋。當次已扣除的轉乘優惠則屬實付差異，不能回填原價。','彙編壹五（二十一）；109.4.14主會財字第1091500103號')
card('住宿費','保六住宿每日上限3,000元','不分職等，每日3,000元上限內檢據覈實。中央平日3,500元、假日4,500元是通用上限，不會自動把保六內規提高。未支出、免費住宿或沒有住宿事實，不能以定額領取。','保六第2(2)點；中央第9、15點與附表一；問答Q12')
card('住宿費','60公里門檻與事前核准','一般出差：機關到出差地60公里以上且有住宿事實，依上限檢據報支。未達60公里須有業務需要並事前經機關核准。保六第3點特定活動的住宿另要求必要性及事前核准，不能只因超過60公里就免簽。','保六第2(2)、3點；中央第9點')
card('住宿費','長期同地出差、套裝與提早住宿','同地出差超過一個月，超過一個月未滿二個月部分按規定數額八折，二個月以上部分七折。套裝交通住宿、多人合住、提前一晚住宿或跨假日，須核對核定行程、費用分攤與實際支出，不用一般單日試算直接核定。','中央第11點；彙編壹九、壹十七','個案認定')
card('雜費','保六雜費：30公里＋4／8小時','一般出差，距離機關所在地30公里以上：未滿4小時不報；滿4小時未滿8小時200元；8小時以上每日上限400元。未達30公里不符這份內規的給付條件。這是保六內部標準，不能套用中央未設距離時數門檻的通案解釋放寬。','保六第2(3)點；問答Q13')
card('雜費','雜費不是餐費，也不逐筆核實','雜費為公務聯繫、傳真、影印、短程車資、購票手續費等零星支出，採定額方式並受機關條件限制。國內旅費已刪除膳費，不另列餐費；供餐並不當然要扣雜費。不能把雜費涵蓋項目再列住宿或交通重複領。','問答Q13；彙編壹二（三）（十）；保六第2(3)點')
card('訓練與特定活動','保六第3點：只補助火車票價','奉派訓練、講習、競賽活動、授課及各項週報等性質會議，只補助服務所在地至到達處所往返交通費（內規文字：僅補助火車票價）；有必要與住宿事實者，住宿須事前核准並檢據。不直接套一般出差雜費。','保六第3點')
card('訓練與特定活動','「僅補助火車票價」尚未寫清楚的範圍','內規未指定自強號、區間車、是否可含公車捷運接駁，也未寫自駕時是否另受火車票價上限限制。網站不自訂答案：此類案件先留下實際工具、必要路程、火車參考價與核准文件，送主計確認；不能將查到的自強號全票當成一律給付標準。','保六第3點文字範圍','待內部確認')
card('訓練與特定活動','訓練機構未供宿而每日往返','中央補助要點允許服務機關衡酌補助起返程、未供宿須每日往返及急要公務召回交通；每日往返上限不得超過國內出差住宿每日上限。保六另有第3點火車票價限制，實際採用的內部上限與計法須由主計確認，不直接套中央較高數額。','訓練補助要點第3、6點；保六第3點','含待確認處')
card('訓練與特定活動','已提供住宿，自己選擇回家','訓練機構已提供必要住宿而個人選擇不住，不補助另覓住宿；除起返程與符合急要公務召回等規定外，不補助自行每日往返。已提供交通工具的部分也不能重複補助。','訓練補助要點第4點；彙編貳三（三）')
card('結報與例外','差畢15日內送出報告表','出差事畢15日內，檢具出差旅費報告表及有關書據報機關審核。核對核派、差勤、實際行程、金額與附件是否一致；遇逾期案件先說明原因依機關程序處理，不由本工具直接判定喪失權利。','中央第4點；彙編壹四')
card('結報與例外','取消、變更、私人行程與突發事故','因私事請假期間不得報旅費。因病或事故阻滯須有確實證明；突發重病住院等依第13點條件，住院雜費最高10日並併審內規。會議取消、親屬緊急變故導致取消住宿等，彙編要求就不可歸責情形從嚴認定，不自動全額給付。','中央第13點；彙編壹九（六）（七）','個案認定')
card('結報與例外','調任、陪同外賓、長期派駐','調任視同出差，由新任機關報支，配偶及直系親屬隨往的交通依第7點。陪同外賓依第6點；經常出差及長期派駐依第15點另定規定。這些案型另有適用條件，應查全文並送主計，不套用本站一般案件試算。','中央第6、7、15點；彙編對應章節','特殊案型')
card('結報與例外','國外出差與其他專案不適用本試算','本知識庫聚焦第二大隊國內出差、國內訓練及保六內部補助。國外／大陸地區出差、移地長駐專案、採購租車、公務車油料等須另循適用規定及預算程序，不以國內自駕或一般旅費直接替代。','適用範圍說明','範圍界線')

pages=[dict(page=i+1,text=p.extract_text()) for i,p in enumerate(PdfReader(ROOT/'sources/compendium-11503.pdf').pages)]
rows=list(csv.reader((ROOT/'tools/taipei-metro-1150830.csv').read_text(encoding='cp950').splitlines()))
metro=[[r[0],r[1],float(r[2]),float(r[3]),r[4]] for r in rows[1:] if len(r)>=5]
data=dict(cards=cards,pages=pages,metro=metro,internal='\n'.join(p.extract_text() for p in PdfReader(ROOT/'sources/internal-114.pdf').pages))
template=(ROOT/'tools/template.html').read_text(encoding='utf-8')
(ROOT/'index.html').write_text(template.replace('/*DATA*/', 'const DATA='+json.dumps(data,ensure_ascii=False).replace('</','<\\/')+';'),encoding='utf-8')
print('Built',len(cards),'cards,',len(pages),'pages,',len(metro),'metro pairs')
